            if (char === quote) {
                let cursor = index + 1;
                while (cursor < text.length && /\s/.test(text[cursor])) cursor++;
                if (cursor >= text.length || text[cursor] === ",") {
                    return index + 1;
                }
            }

            if (char === '"' || char === "'") {
                innerQuote = char;
                quoteRole = seenSeparator ? "value" : "key";
                index++;
                continue;
            }

            if (char === ":" && !seenSeparator) {
                seenSeparator = true;
                index++;
                continue;
            }

